const F=['b','a','r','n','atk','def'],bit=i=>1<<i,pop=m=>{let n=0;for(m&=63;m;m&=m-1)n++;return n},ent=p=>p<=0||p>=1?0:-p*Math.log2(p)-(1-p)*Math.log2(1-p);
let cards,weights,universe,profiles,baseActions,fastCache,allocationCache;
const weak=(t,g)=>{let m=0;if((t.b&128)?!!(t.b&g.b&127):t.b===g.b)m|=1;if(t.a===g.a)m|=2;if(t.r===g.r)m|=4;if(t.nm&g.nm)m|=8;if(t.atk===g.atk)m|=16;if(t.def===g.def)m|=32;return m},strict=(t,g)=>(weak(t,g)&~1)|(t.b===g.b?1:0),exact=(t,g)=>strict(t,g)===63,mass=xs=>xs.reduce((s,i)=>s+weights[i],0);
const makeRandom=seed=>{let x=seed>>>0;return()=>{x=(1664525*x+1013904223)>>>0;return x/2**32}},sample=(xs,r)=>{let p=r()*mass(xs);for(const i of xs){p-=weights[i];if(p<0)return i}return xs.at(-1)};
function selectBase(limit=64){const candidates=universe,total=mass(candidates),metrics=[];for(const index of universe){let solve=0,matches=0;const outcomes=new Map;for(const ti of candidates){const t=cards[ti],w=weights[ti],wm=weak(t,cards[index]),sm=strict(t,cards[index]),k=`${wm}|${sm}|${exact(t,cards[index])?1:0}`;if(exact(t,cards[index]))solve+=w;matches+=pop(sm)*w;outcomes.set(k,(outcomes.get(k)||0)+w)}let entropy=0;for(const x of outcomes.values()){const p=x/total;entropy-=p*Math.log2(p)}metrics.push({index,solve:solve/total,matches:matches/total,entropy})}const out=new Set([...candidates].sort((a,b)=>weights[b]-weights[a]).slice(0,32));[...metrics].sort((a,b)=>b.solve-a.solve||b.matches-a.matches).slice(0,32).forEach(x=>out.add(x.index));[...metrics].sort((a,b)=>b.entropy-a.entropy).slice(0,limit).forEach(x=>{if(out.size<limit)out.add(x.index)});return[...out].slice(0,limit)}
function dynamic(state,limit=36){const total=mass(state.candidates),old=pop(state.m),quick=[];for(const index of universe){if(state.g.has(index))continue;let solve=0,nm=0;const bits=[0,0,0,0,0,0],guess=cards[index];for(const ti of state.candidates){const t=cards[ti],w=weights[ti],wm=weak(t,guess),sm=strict(t,guess);if(exact(t,guess))solve+=w;nm+=(pop(state.m|sm)-old)*w;for(let b=0;b<6;b++)if(wm&bit(b))bits[b]+=w}quick.push({index,solve:solve/total,nm:nm/total,info:bits.reduce((s,x)=>s+ent(x/total),0)})}const out=new Set;[...quick].sort((a,b)=>b.solve-a.solve||b.nm-a.nm).slice(0,20).forEach(x=>out.add(x.index));[...quick].sort((a,b)=>b.info-a.info).slice(0,12).forEach(x=>out.add(x.index));[...state.candidates].sort((a,b)=>weights[b]-weights[a]).slice(0,12).forEach(i=>out.add(i));return[...out].slice(0,limit)}
function choose(state,actions,final,cache){const key=`${final?1:0}|${state.candidates.join(',')}|${[...state.g].sort((a,b)=>a-b).join(',')}`;if(cache.has(key))return cache.get(key);const total=mass(state.candidates);if(final){const groups=new Map;for(const i of state.candidates){const c=cards[i],s=`${c.b}|${c.a}|${c.r}|${c.nm}|${c.atk}|${c.def}`;if(!groups.has(s))groups.set(s,{index:i,w:0});groups.get(s).w+=weights[i]}const x=[...groups.values()].filter(x=>!state.g.has(x.index)).sort((a,b)=>b.w-a.w)[0];if(x){cache.set(key,x.index);return x.index}}let best=null;const usable=new Set(actions);[...state.candidates].sort((a,b)=>weights[b]-weights[a]).slice(0,24).forEach(i=>usable.add(i));for(const index of usable){if(state.g.has(index))continue;let solve=0,matches=0;const outcomes=new Map,guess=cards[index];for(const ti of state.candidates){const t=cards[ti],w=weights[ti],wm=weak(t,guess),sm=strict(t,guess),k=`${wm}|${sm}|${wm&1?t.b:''}|${wm&8?t.nm:''}`;if(exact(t,guess))solve+=w;matches+=pop(sm)*w;outcomes.set(k,(outcomes.get(k)||0)+w)}let info=0;for(const x of outcomes.values()){const p=x/total;info-=p*Math.log2(p)}const score=final?[solve/total,matches/total,info]:[info,solve/total,matches/total];if(!best){best={index,score};continue}for(let j=0;j<3;j++){if(Math.abs(score[j]-best.score[j])<1e-12)continue;if(score[j]>best.score[j])best={index,score};break}}cache.set(key,best?.index);return best?.index}
function alloc(t,h,c){const key=`${t}|${h}|${c}`;if(allocationCache.has(key))return allocationCache.get(key);let best={solved:0,matches:0,profile:null};for(const p of profiles){if(p.hints>h||p.challenges>c)continue;let solved=0,matches=0;for(const[k,q]of p.distribution){const[s,m,uh,uc]=k.split('|').map(Number);if(s){const future=alloc(t-1,h-uh,c-uc);solved+=q*(1+future.solved);matches+=q*(6+future.matches)}else matches+=q*m}if(solved>best.solved+1e-12||Math.abs(solved-best.solved)<=1e-12&&matches>best.matches)best={solved,matches,profile:p}}allocationCache.set(key,best);return best}
function open(targetIndex,r){const f=Math.floor(r()*6),v=cards[targetIndex][F[f]];return{target:targetIndex,candidates:universe.filter(i=>cards[i][F[f]]===v),k:bit(f),m:0,g:new Set,cache:new Map}}
const clone=(s,target=s.target)=>({target,candidates:[...s.candidates],k:s.k,m:s.m,g:new Set(s.g),cache:new Map});
function hint(s,res,r){const u=[0,1,2,3,4,5].filter(f=>!(s.k&bit(f)));if(!res.h||!u.length)return false;const f=u[Math.floor(r()*u.length)],v=cards[s.target][F[f]];res.h--;s.k|=bit(f);s.candidates=s.candidates.filter(i=>cards[i][F[f]]===v);return true}
function challenge(s,res,index){if(!res.c)return false;res.c--;s.g.add(index);const t=cards[s.target],g=cards[index];if(exact(t,g))return true;const wm=weak(t,g),sm=strict(t,g);s.k|=wm;s.m|=sm;s.candidates=s.candidates.filter(i=>{const c=cards[i],w=weak(c,g),st=strict(c,g);return w===wm&&st===sm&&!exact(c,g)&&(!(w&1)||c.b===t.b)&&(!(w&8)||c.nm===t.nm)});return false}
function baseContinue(state,res,t,r){let solved=0,matches=0;for(let p=0;p<t&&res.c;p++){let done=false;while(res.c&&!done){const profile=alloc(t-p,res.h,res.c).profile;if(!profile)break;let moved=false;for(let x=0;x<profile.pattern.length&&!done;x++){if(profile.pattern[x]==='0'){moved=hint(state,res,r)||moved;continue}const index=choose(state,baseActions,!profile.pattern.slice(x+1).includes('1'),fastCache);if(index==null)break;moved=true;done=challenge(state,res,index)}if(!moved)break}if(!done){matches+=pop(state.m);break}solved++;matches+=6;if(p+1<t)state=open(sample(universe,r),r)}return[solved,matches]}
function value(initial,res0,t,action,seeds){let out=[0,0];for(const seed of seeds){const r=makeRandom(seed),target=sample(initial.candidates,r),s=clone(initial,target),res={h:res0.h,c:res0.c};let done=action.type==='hint'?(hint(s,res,r),false):challenge(s,res,action.index),v;if(done){v=[1,6];if(t>1){const f=baseContinue(open(sample(universe,r),r),res,t-1,r);v=[1+f[0],6+f[1]]}}else v=baseContinue(s,res,t,r);out[0]+=v[0]/seeds.length;out[1]+=v[1]/seeds.length}return out}
self.onmessage=({data})=>{try{cards=data.cards;weights=cards.map(c=>data.pool==='md'?c.wm:c.wa);universe=cards.map((c,i)=>weights[i]>0?i:-1).filter(i=>i>=0);profiles=data.profiles;baseActions=data.baseActions?.length?data.baseActions:selectBase(64);fastCache=new Map;allocationCache=new Map;const state={target:null,candidates:data.candidates,k:data.knownMask,m:data.matchedMask,g:new Set(data.guessed),cache:new Map},res={h:data.hints,c:data.challenges},challengeIndex=choose(state,dynamic(state),false,state.cache),options=challengeIndex==null?[]:[{type:'challenge',index:challengeIndex}];if(res.h&&state.k!==63)options.push({type:'hint'});let seed=data.seed>>>0||0x524f4c4c;const random=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/2**32},seeds=Array.from({length:data.rollouts||4},()=>Math.floor(random()*2**32));const compared=options.map(action=>({action,value:value(state,res,data.remainingPuzzles,action,seeds)})).sort((a,b)=>b.value[0]-a.value[0]||b.value[1]-a.value[1]);postMessage({type:'complete',best:compared[0],compared,rollouts:seeds.length,profileSamples:data.profileSamples})}catch(error){postMessage({type:'error',message:error.stack||String(error)})}};
